#!/usr/bin/env bun
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.resolve(here, "..");
const entry = path.join(pkgRoot, "src/cli/index.ts");
const generatedDir = path.join(pkgRoot, "src/generated");

const result = await Bun.build({
  entrypoints: [entry],
  target: "node",
  minify: true,
});

if (!result.success) {
  for (const log of result.logs) console.error(log);
  throw new Error("opencompany-brain CLI bundle failed");
}

const artifact = result.outputs[0];
if (!artifact) throw new Error("opencompany-brain CLI bundle produced no output");
const code = (await artifact.text())
  .replace(/^#!\/usr\/bin\/env bun/, "#!/usr/bin/env node")
  .replace(/^\/\/ @bun\n/m, "");
const base64 = Buffer.from(code, "utf8").toString("base64");

const module = `// GENERATED by scripts/build-bundle.mjs - do not edit by hand.
// Run \`bun run bundle\` in packages/brain to regenerate after changing the CLI.
// The base64 payload is the self-contained \`opencompany-brain\` CLI (minisearch inlined).
export const BRAIN_CLI_BUNDLE_BASE64 =
  "${base64}";

export function getBrainCliSource() {
  return Buffer.from(BRAIN_CLI_BUNDLE_BASE64, "base64").toString("utf8");
}
`;

await mkdir(generatedDir, { recursive: true });
await writeFile(path.join(generatedDir, "cli-bundle.ts"), module, "utf8");

console.log(
  `opencompany-brain CLI bundle: ${(code.length / 1024).toFixed(1)} KB raw, ${(base64.length / 1024).toFixed(1)} KB base64`,
);
